BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-22697'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='BL0067' OR source_url ~ '[?&]id=22697(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='c52b0067-d5bd-4e64-aefb-153065822697' OR slug='sam-rat-uthit-hat-yai-land-bl0067' OR (abs(latitude-7.009376)<0.0001 AND abs(longitude-100.458554)<0.0001 AND abs(land_area_sqm-11869.6)<1)) THEN RAISE NOTICE 'SAM BL0067 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('c52b0067-d5bd-4e64-aefb-153065822697', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'business', 'sale', 'whole_property', 'ที่ดินถนนราษฎร์อุทิศ หาดใหญ่ ติดถนน 2 ด้าน 7 ไร่ 1 งาน 67.4 ตร.ว.', 'รายละเอียดทรัพย์

ที่ดินติดถนนราษฎร์อุทิศ ตำบลหาดใหญ่ อำเภอหาดใหญ่ จังหวัดสงขลา จำนวน 10 แปลงติดกัน รวม 7 ไร่ 1 งาน 67.4 ตร.ว. หรือ 2,967.4 ตร.ว. (11,869.6 ตร.ม.) โฉนดเลขที่ 1277, 13640, 13641, 13642 และ 43178–43183 ราคาประกาศขาย SAM 193,756,000 บาท รหัส BL0067 ต้นทางแสดงราคาประมาณ 65,295 บาท/ตร.ว. ใช้ราคารวมเป็นหลัก

ที่ดินรูปหลายเหลี่ยม ติดถนน 2 ด้าน ด้านตะวันออกกว้างประมาณ 35 เมตร ด้านตะวันตกประมาณ 62 เมตร ลึกประมาณ 205 เมตร SAM ระบุผังเมืองสีชมพู ถนนราษฎร์อุทิศเป็นทางสาธารณประโยชน์ตามต้นทาง ผิวลาดยางกว้างประมาณ 18 เมตร เขตทางประมาณ 30 เมตร

ข้อควรทราบเกี่ยวกับทรัพย์

ที่ดินบางส่วนของโฉนด 1277 มีสภาพเป็นถนนราษฎร์อุทิศ เนื้อที่ประมาณ 1 งาน 63 ตร.ว. หรือ 163 ตร.ว. ซึ่งรวมในพื้นที่ทั้งหมดข้างต้น ขนาดด้านเหนือประมาณ 28.5 เมตร ด้านใต้ 23 เมตร ด้านตะวันตก 12 เมตร และด้านตะวันออก 17 เมตร ผู้สนใจควรตรวจแนวเขต สถานะสิทธิและพื้นที่ใช้งานจริงก่อนเสนอซื้อ ไม่ควรถือว่าพื้นที่ทั้งหมดสามารถพัฒนาได้โดยไม่มีข้อจำกัด

แม้ SAM จัดหมวดประชาสัมพันธ์เป็นที่ดินเปล่า ผู้ซื้อต้องรับโอนกรรมสิทธิ์สิ่งปลูกสร้างตามรายการที่ SAM รับโอน คืออาคารร้านอาหารชั้นเดียวไม่มีเลขที่ ข้อมูลสำรวจในคำบรรยายระบุร้านค้าชั้นเดียว ส่วนโล่งหลังคาคลุม 1 หลังและซุ้มขายน้ำ ลักษณะไม่มั่นคงถาวรและรื้อถอนได้ง่าย

รูปจาก SAM วันที่ 20 กุมภาพันธ์ 2569 แสดงพื้นที่เปิดและเศษวัสดุรื้อถอนจำนวนมาก ซึ่งต่างจากรายการสิ่งปลูกสร้างในคำบรรยาย จึงต้องยืนยันสภาพปัจจุบัน รายการที่ต้องรับโอน และผู้รับผิดชอบการขนย้ายเศษวัสดุกับ SAM ไม่ถือว่ารูปถ่ายยกเลิกหน้าที่รับโอนตามเงื่อนไขต้นทาง

ทำเลและการเดินทาง

อยู่ในย่านที่อยู่อาศัยและพาณิชยกรรม ใกล้วัดโคกสมานคุณ โรงเรียนวัดโคกสมานคุณและตลาดกิมหยง ตามข้อมูล SAM จากแยกต่างระดับควนลังมุ่งหน้าเมืองหาดใหญ่บนถนนเพชรเกษม (ทล.4) ผ่านการไฟฟ้าส่วนภูมิภาค ที่ว่าการอำเภอหาดใหญ่และโรงเรียนพลวิทยา เลี้ยวซ้ายเข้าถนนราษฎร์อุทิศประมาณ 540 เมตร ทรัพย์อยู่ซ้ายมือ

ภาพและข้อมูลต้นทาง

ภาพจริงและผังจาก SAM รวม 15 ภาพ พร้อมผังส่วนที่เป็นถนน พิกัด 7.009376, 100.458554 ดึงจากลิงก์นำทาง SAM และตรงกับลิงก์แผนที่ เป็นจุดอ้างอิง ไม่ใช่แนวเขตรังวัด

ราคาและสถานะซื้อตรงตรวจจากหน้า SAM วันที่ 15 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส BL0067 เพื่อยืนยันราคา สถานะพร้อมขาย การนัดชม สิ่งปลูกสร้างและเงื่อนไขล่าสุด', 193756000, false, 11869.6, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'ถนนราษฎร์อุทิศ', 'เข้าจากถนนเพชรเกษมประมาณ 540 เมตร', 'ถนนราษฎร์อุทิศ', 7.009376, 100.458554, 'สงขลา', 'หาดใหญ่', 'หาดใหญ่', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-rat-uthit-hat-yai-land-bl0067') RETURNING id INTO property_listing_id;
