INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=22697&keyref=', 'BL0067', now(), 'Checked2026-09-15. THB193756000,10 adjoining deeds,11869.6sqm. Road-occupied deed1277 portion163sq.wah included. Mandatory registered restaurant transfer retained despite vacant-land category and photos showing open ground/debris. Text/photo inventory difference and removal responsibility disclosed.15 original images; field date2026-02-20. Navigation/map agree. All-status code/page/deed/nearby query returned no matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Rat Uthit Road Land, Hat Yai — Two Road Frontages, THB 193.756M', 'Ten adjoining land plots on Rat Uthit Road, Hat Yai, Hat Yai District, Songkhla, totalling 7 rai 1 ngan 67.4 sq.wah, or 2,967.4 sq.wah (11,869.6 sq.m.). Chanote titles 1277, 13640, 13641, 13642 and 43178–43183. SAM announced price THB 193,756,000, asset BL0067; source unit price approximately THB 65,295/sq.wah, with total price governing.

Polygonal site with roads on two sides, approximately 35 m eastern frontage,62 m western frontage and205 m depth. SAM reports pink zoning. Rat Uthit Road is public according to SAM, with approximately18 m paved carriageway and30 m right of way.

Material disclosure: part of deed1277 physically forms Rat Uthit Road, approximately163 sq.wah included in the total land area. Source dimensions approximately28.5 m north,23 m south,12 m west and17 m east. Verify boundaries, rights and usable area; total title area is not unrestricted development area.

SAM labels the property vacant land for marketing/search purposes but expressly requires the buyer to accept transfer of the registered structure: an unnumbered single-storey restaurant. The textual survey describes a single-storey shop, one open covered structure and a drinks kiosk, of non-permanent,easily removable construction.

SAM photos dated20 February2026 show open ground and substantial demolition debris, differing from the written structure inventory. Confirm present condition, mandatory transfer inventory and responsibility for debris removal with SAM. Photos do not cancel the source''s structure-transfer requirement.

Residential/commercial surroundings near Wat Khok Saman Khun,its school and Kim Yong Market. From Khuan Lang interchange toward Hat Yai on Phetkasem Highway4,pass the electricity authority,district office and Pholwitthaya School,then turn left into Rat Uthit Road for approximately540 m; property on the left.

Fifteen authentic source photos/plans including the road-occupied portion. Navigation/map agree7.009376,100.458554,a reference pin rather than a surveyed boundary. Price/direct-sale status checked15 September2026. Contact SAM02-686-1888,sales@sam.or.th or LINE@samline quoting BL0067 to confirm availability,price,viewing,structures and terms.', 'Rat Uthit Road', 'Approximately540 metres from Phetkasem Road', 'Rat Uthit Road', 'Hat Yai', 'Hat Yai', 'Songkhla', 'Rat Uthit Road Land, Hat Yai — Two Road Frontages, THB 193.756M', 'Ten adjoining plots,11869.6sqm,THB193756000. Road-occupied area and mandatory registered structure transfer disclosed.', 'published', 'ai_assisted', now(), 'rat uthit road land, hat yai — two road frontages, thb 193.756m ten adjoining land plots on rat uthit road, hat yai, hat yai district, songkhla, totalling 7 rai 1 ngan 67.4 sq.wah, or 2,967.4 sq.wah (11,869.6 sq.m.). chanote titles 1277, 13640, 13641, 13642 and 43178–43183. sam announced price thb 193,756,000, asset bl0067; source unit price approximately thb 65,295/sq.wah, with total price governing.

